setInterval(()=>{if(page==='lineups'&&!luFormDirty&&!$lu('lu-editor').open)luFetch()},3000);window.addEventListener('beforeunload',e=>{if(luFormDirty){e.preventDefault();e.returnValue=''}});
function luMediaView(item,parent){if(!item.media?.length)return;for(const [kind,title]of [['images','详细点位截图'],['videos','详细演示视频']]){const files=item.media.filter(m=>m.kind===kind);if(!files.length)continue;parent.append(luEl('h3',title));for(const file of files){if(kind==='images'){const a=luEl('a');a.href=file.url;a.target='_blank';a.rel='noopener';const img=luEl('img');img.src=file.url;img.alt=item.title+'详细点位截图';img.loading='lazy';img.className='lu-upload-media';a.append(img);parent.append(a)}else{const v=luEl('video');v.src=file.url;v.controls=true;v.preload='metadata';v.playsInline=true;v.className='lu-upload-media';parent.append(v)}}}}
function luMediaEditor(form,item,ms,as){let files=[...(item.media||[])],ids=[...(item.attachments||[])],uploading=false,lockedMap=ms.value,lockedAgent=as.value;const box=luEl('section');box.append(luEl('h3','详细截图和视频'),luEl('p','截图：PNG/JPEG/WebP，单张≤20MB，最多8张。视频：MP4/WebM/MOV，单个≤200MB、≤3分钟，最多3个。统一转为1280×720；截图JPEG，视频MP4/30fps。'));const status=luEl('p');status.role='status';const list=luEl('div');function paint(){list.replaceChildren();for(const f of files){const row=luEl('div');const preview=luEl(f.kind==='images'?'img':'video');preview.src=f.url;preview.className='lu-upload-media';if(f.kind==='videos'){preview.controls=true;preview.preload='metadata'}else preview.alt='已上传详细截图';const remove=luEl('button','移除此'+(f.kind==='images'?'截图':'视频'));remove.type='button';remove.onclick=()=>{files=files.filter(x=>x.id!==f.id);ids=ids.filter(id=>id!==f.id);luFormDirty=true;paint()};row.append(preview,remove);list.append(row)}}
for(const [kind,title,accept]of [['images','上传详细截图','image/png,image/jpeg,image/webp'],['videos','上传详细视频','video/mp4,video/webm,video/quicktime']]){const label=luEl('label',title),input=luEl('input');input.type='file';input.accept=accept;label.append(input);box.append(label);input.onchange=async()=>{const file=input.files[0];if(!file)return;if(uploading){status.textContent='正在处理上一文件，请稍候';input.value='';return}if(file.size>(kind==='images'?20:200)*1024*1024){status.textContent='文件超过大小限制';input.value='';return}if(files.filter(f=>f.kind===kind).length>=(kind==='images'?8:3)){status.textContent='已达到此类附件数量上限';input.value='';return}uploading=true;luFormDirty=true;ms.disabled=as.disabled=true;form.querySelector('button[type=submit]').disabled=true;status.textContent='正在上传…';try{const result=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/media?'+new URLSearchParams({mapId:ms.value,agentId:as.value,kind}));x.timeout=240000;x.setRequestHeader('Content-Type','application/octet-stream');x.upload.onprogress=e=>{if(e.lengthComputable)status.textContent=e.loaded===e.total?'上传完成，正在统一尺寸和格式…':'上传中 '+Math.round(e.loaded/e.total*100)+'%'};x.onload=()=>{try{const d=JSON.parse(x.responseText);x.status<300?resolve(d):reject(Error(d.error||'上传失败'))}catch(e){reject(Error('上传响应异常'))}};x.onerror=()=>reject(Error('网络中断，请重试'));x.ontimeout=()=>reject(Error('处理超时，请使用更短的视频'));x.send(file)});files.push(result);ids.push(result.id);lockedMap=ms.value;lockedAgent=as.value;paint();status.textContent='附件已处理，请保存点位后发布给游客。'}catch(e){status.textContent=e.message}finally{uploading=false;ms.disabled=as.disabled=false;form.querySelector('button[type=submit]').disabled=false;input.value=''}}}
box.append(status,list);paint();form.append(box);for(const select of [ms,as]){const old=select.onchange;select.onchange=e=>{if(ids.length){select.value=select===ms?lockedMap:lockedAgent;status.textContent='附件按地图和英雄存储，请先移除附件再更改地图或英雄。';return}old?.(e)}}return {getIds:()=>ids,isBusy:()=>uploading};}
